    best = None
    for addr, name in symbols:
        if addr <= target:
            best = (addr, name)
        else:
            break
    if best:
        offset = target - best[0]
        print(f"  {frame} pc 0x{target:x} -> {best[1]}+0x{offset:x}")
    else:
        print(f"  {frame} pc 0x{target:x} -> ???")
