# Only .dynsym, no .symtab - it's fully stripped. Let's look for all FUNC symbols 
# between our target addresses to narrow down what functions these really are.

python3 << 'EOF'
import subprocess

result = subprocess.run(['readelf', '-sW', '/tmp/symbols/libmonosgen-2.0.so'], 
                       capture_output=True, text=True)

symbols = []
for line in result.stdout.splitlines():
    parts = line.split()
    if len(parts) >= 8 and 'FUNC' in parts:
        try:
            addr = int(parts[1], 16)
            size = int(parts[2])
            name = parts[7] if len(parts) > 7 else parts[-1]
            if addr > 0:
                symbols.append((addr, size, name))
        except (ValueError, IndexError):
            continue

symbols.sort()

targets = {
    '#01': 0x222098,
    '#02': 0x222234,
    '#03': 0x19bac0,
    '#06': 0x19bc14,
}

for frame, target in sorted(targets.items()):
    # Find the function that contains the target address (addr <= target < addr+size)
    found = False
    for addr, size, name in symbols:
        if addr <= target < addr + size:
            offset = target - addr
            print(f"  {frame} pc 0x{target:x} -> {name}+0x{offset:x} (func at 0x{addr:x}, size={size})")
            found = True
            break
    if not found:
        # Nearest preceding
        best = None
        for addr, size, name in symbols:
            if addr <= target:
                best = (addr, size, name)
            else:
                break
        if best:
            offset = target - best[0]
            print(f"  {frame} pc 0x{target:x} -> {best[2]}+0x{offset:x} (nearest, func at 0x{best[0]:x}, size={best[1]})")
        else:
            print(f"  {frame} pc 0x{target:x} -> ???")
EOF

