# The sizes don't cover our addresses - these are truly internal (non-exported) functions.
# Let's look at ALL symbols (not just FUNC) in those ranges to find what's there.

python3 << 'EOF'
import subprocess

result = subprocess.run(['readelf', '-sW', '/tmp/symbols/libmonosgen-2.0.so'], 
                       capture_output=True, text=True)

symbols = []
for line in result.stdout.splitlines():
    parts = line.split()
    if len(parts) >= 8:
        try:
            addr = int(parts[1], 16)
            size = int(parts[2])
            stype = parts[3]
            name = parts[7] if len(parts) > 7 else parts[-1]
            if addr > 0 and stype == 'FUNC':
                symbols.append((addr, size, name))
        except (ValueError, IndexError):
            continue

symbols.sort()

# Print all funcs in range 0x19b000 - 0x19d000 and 0x221000 - 0x223000
print("=== Functions near 0x19bxxx ===")
for addr, size, name in symbols:
    if 0x198000 <= addr <= 0x19d000:
        print(f"  0x{addr:x} size={size} {name}")

print("\n=== Functions near 0x222xxx ===")
for addr, size, name in symbols:
    if 0x21e000 <= addr <= 0x224000:
        print(f"  0x{addr:x} size={size} {name}")
EOF

